local a=require("index")local b;local function c(d,e)if e==nil then e="%s"end;local f={}for g in string.gmatch(d,"([^"..e.."]+)")do table.insert(f,g)end;return f end;local h={map=function(i,j)if i[2]=="sender"then a.addSender(j,i[3])end;if i[2]=="receiver"then a.addReceiver(j,i[3],i[4])end end,list=function(i,j)print("Senders:")print(textutils.serialise(a.getAllSenders(j)))print("Receivers:")print(textutils.serialise(a.getAllReceivers(j)))end,search=function(i,j)local k=i[3]if i[2]=="sender"then local l=a.getAllSenders(j)[i[3]]if l==nil then print("Sender not found: "..i[3])else print("Sender found: "..i[3])end elseif i[2]=="receiver"then local m=a.getReceiver(j,i[3])if m==nil then print("Receiver not found: "..i[3])else print("Receiver found: "..i[3])end else print("Unknown search type: "..i[2])end end,exit=function(i,j)print("Exiting...")return false end,help=function(i,j)print("Available commands:")print("map sender <name> - Add a sender to the index")print("map receiver <name> <address> - Add a receiver to the index")print("list - List all senders and receivers")print("search sender <name> - Search for a sender by name")print("search receiver <address> - Search for a receiver by address")print("exit - Exit the program")end}function b.processCommandLoop(j)while true do local i=c(read()," ")if h[i[1]]==nil then print("Unknown command: "..i[1])else local n=h[i[1]](i,j)if n==false then break end end end end;return b
